import { checkPermission, PermissionType } from "modules/permissions/utils";
import { useState } from "react";
import { Alert, Linking } from "react-native";
import {
  type Asset,
  type CameraOptions,
  type ImageLibraryOptions,
  launchCamera,
  launchImageLibrary,
} from "react-native-image-picker";

export function useUploadPhoto(
  onImageSelected?: (image: Asset | null) => void,
) {
  const [isListOpen, setIsListOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedAsset, setSelectedAsset] = useState<Asset | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  function handleRemovePhoto() {
    if (!selectedImage) return;
    setIsListOpen(false);
    setSelectedImage(null);
    setSelectedAsset(null);
    onImageSelected?.(null);
  }

  async function handleTakePhoto() {
    setIsLoading(true);

    try {
      setIsListOpen(false);
      const hasPermission = await checkPermission(PermissionType.CAMERA);

      if (!hasPermission) {
        Alert.alert(
          "Permission Required",
          "Please go to settings and grant camera access to take photos.",
          [
            { text: "OK" },
            { text: "Go to settings", onPress: () => Linking.openSettings() },
          ],
        );
        return;
      }

      const options: CameraOptions = {
        mediaType: "photo",
        includeBase64: true,
        maxHeight: 2000,
        maxWidth: 2000,
        quality: 0.8,
      };

      await launchCamera(options, (response) => {
        if (response.didCancel || response.errorMessage) return;

        if (response.assets?.[0]) {
          const asset = response.assets[0];
          const imageUri = asset.uri;

          if (imageUri) {
            setSelectedImage(imageUri);
            setSelectedAsset(asset);
            onImageSelected?.(asset);
          }
        }
      });
    } catch (error) {
      Alert.alert("Error", "Failed to take photo. Please try again.", [
        { text: "OK" },
      ]);
      console.error("Camera error:", error);
    } finally {
      setIsLoading(false);
    }
  }

  async function handleChoosePhoto() {
    setIsLoading(true);

    try {
      setIsListOpen(false);
      const hasPermission = await checkPermission(PermissionType.PHOTO_LIBRARY);

      if (!hasPermission) {
        Alert.alert(
          "Permission Required",
          "Please go to settings and grant photo library access to select images.",
          [
            { text: "OK" },
            { text: "Go to settings", onPress: () => Linking.openSettings() },
          ],
        );
        return;
      }

      const options: ImageLibraryOptions = {
        mediaType: "photo",
        includeBase64: true,
        maxHeight: 2000,
        maxWidth: 2000,
      };

      await launchImageLibrary(options, (response) => {
        if (response.didCancel || response.errorMessage) return;

        if (response.assets?.[0]) {
          const asset = response.assets[0];
          const imageUri = asset.uri;

          if (imageUri) {
            setSelectedImage(imageUri);
            setSelectedAsset(asset);
            onImageSelected?.(asset);
          }
        }
      });
    } catch (error) {
      Alert.alert("Error", "Failed to select image. Please try again.", [
        { text: "OK" },
      ]);
      console.error("Image picker error:", error);
    } finally {
      setIsLoading(false);
    }
  }

  return {
    isListOpen,
    selectedImage,
    selectedAsset,
    isLoading,
    setIsListOpen,
    setSelectedImage,
    setSelectedAsset,
    handleRemovePhoto,
    handleTakePhoto,
    handleChoosePhoto,
  };
}

