      const thumbnail = await createThumbnail({
        url: asset.uri,
        timeStamp: 1000,
        format: "jpeg",
        maxWidth: 800,
        maxHeight: 600,
      });

      const stat = await RNFS.stat(thumbnail.path);
      thumbnailWidth = thumbnail.width;
      thumbnailHeight = thumbnail.height;
      thumbnailSize = Number(stat.size);
      thumbnailSource = new UploadSource.File({ filename: thumbnail.path });

      blurhash = await Blurhash.encode(`file://${thumbnail.path}`, 3, 3);
    } catch {
      // Thumbnail generation is best-effort — send without it if it fails
    }

    // createThumbnail uses AVAssetImageGenerator with appliesPreferredTrackTransform=true,
    // so thumbnail dimensions are rotation-corrected. Derive video display dimensions
    // from thumbnail orientation: whichever raw dimension (1920 or 1080) belongs to
    // width vs height is determined by whether the thumbnail is landscape or portrait.
    const thumbIsLandscape = thumbnailWidth >= thumbnailHeight;
    const videoWidth = thumbIsLandscape
      ? Math.max(assetWidth, assetHeight)
      : Math.min(assetWidth, assetHeight);
    const videoHeight = thumbIsLandscape
      ? Math.min(assetWidth, assetHeight)
      : Math.max(assetWidth, assetHeight);

    const videoHandle = timeline.sendVideo(fileSource, thumbnailSource, {
      height: BigInt(videoHeight),
      width: BigInt(videoWidth),
      mimetype: type,
      size: BigInt(asset.fileSize ?? 0),
      duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
      thumbnailInfo: thumbnailSource
        ? {
            height: BigInt(thumbnailHeight),
            width: BigInt(thumbnailWidth),
            mimetype: "image/jpeg",
            size: BigInt(thumbnailSize),
          }
        : undefined,
      thumbnailSource: undefined,
      blurhash,
    });
    await videoHandle.join();
  } else {
    const imageHandle = timeline.sendImage(
      fileSource,
      new UploadSource.File({
        filename: decodeURIComponent(asset.uri.replace("file://", "")),
      }),
      {
        height: BigInt(assetHeight),
        width: BigInt(assetWidth),
        mimetype: type,
        size: BigInt(asset.fileSize ?? 0),
        thumbnailInfo: {
          height: BigInt(assetHeight),
          width: BigInt(assetWidth),
          mimetype: type,
          size: BigInt(asset.fileSize ?? 0),
        },
        thumbnailSource: undefined,
        blurhash: "",
        isAnimated: false,
      },
    );
    await imageHandle.join();
  }
};

public static sendEvent = async (
  roomId: string,
  eventType: string,
  content: string,
) => {
  const room = MatrixCore.getRoom(roomId);
  await room.sendRaw(eventType, content);

